#!/usr/bin/env python3
"""A shared link shortener for a study group, backed by one JSON file on a mount."""
import json
import os
import random
import re
import string
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse

DATA_DIR = os.environ.get("DATA_DIR", "/data")
LINKS_FILE = os.path.join(DATA_DIR, "links.json")
PORT = int(os.environ.get("PORT", "8080"))

CODE_RE = re.compile(r"^[a-zA-Z0-9_-]{3,20}$")
REDIRECT_RE = re.compile(r"^/([a-zA-Z0-9_-]{3,20})$")
RESERVED = {"api", "healthz", "favicon.ico"}
ALPHABET = string.ascii_letters + string.digits


def load():
    try:
        with open(LINKS_FILE) as handle:
            return json.load(handle)
    except (FileNotFoundError, json.JSONDecodeError):
        return []


def save(links):
    tmp = LINKS_FILE + ".tmp"
    with open(tmp, "w") as handle:
        json.dump(links, handle, indent=2)
    os.replace(tmp, LINKS_FILE)


def now():
    return datetime.now(timezone.utc).isoformat()


def is_valid_url(url):
    try:
        parsed = urlparse(url)
    except ValueError:
        return False
    return parsed.scheme in ("http", "https") and bool(parsed.netloc)


def new_code(existing_codes):
    for _ in range(50):
        code = "".join(random.choices(ALPHABET, k=6))
        if code not in existing_codes:
            return code
    raise RuntimeError("could not allocate a unique code")


