        self.wfile.write(raw)

    def send_html(self, status, body):
        raw = body.encode()
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    def read_json(self):
        length = int(self.headers.get("Content-Length") or 0)
        if length == 0:
            return {}
        try:
            return json.loads(self.rfile.read(length))
        except json.JSONDecodeError:
            return None

    def do_GET(self):
        if self.path == "/healthz":
            return self.send_html(200, "ok")
        if self.path in ("/", "/index.html"):
            return self.send_html(200, PAGE)
        if self.path == "/api/links":
            return self.send_json(200, {"links": load()})

        match = REDIRECT_RE.match(self.path)
        if match and match.group(1) not in RESERVED:
            code = match.group(1)
            links = load()
            for link in links:
                if link["code"] == code:
                    link["clicks"] += 1
                    save(links)
                    self.send_response(302)
                    self.send_header("Location", link["url"])
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
            return self.send_html(404, "<h1>404</h1><p>No link with that code.</p>")

        return self.send_json(404, {"error": "not found"})

    def do_POST(self):
        if self.path == "/api/links":
            body = self.read_json()
            if body is None:
                return self.send_json(400, {"error": "body is not JSON"})
            url = str(body.get("url", "")).strip()
            if not is_valid_url(url):
                return self.send_json(400, {"error": "a valid http(s) URL is required"})

            links = load()
            existing_codes = {link["code"] for link in links}

            custom_code = str(body.get("code") or "").strip()
            if custom_code:
                if not CODE_RE.match(custom_code):
                    return self.send_json(400, {"error": "slug must be 3-20 letters, numbers, - or _"})
                if custom_code in RESERVED or custom_code in existing_codes:
                    return self.send_json(409, {"error": "that slug is already taken"})
                code = custom_code
            else:
                code = new_code(existing_codes)

            link = {
                "code": code,
                "url": url,
                "clicks": 0,
                "created_at": now(),
            }
            links.append(link)
            save(links)
            return self.send_json(201, link)

        return self.send_json(404, {"error": "not found"})

    def do_DELETE(self):
        prefix = "/api/links/"
        if not self.path.startswith(prefix):
            return self.send_json(404, {"error": "not found"})
        code = self.path[len(prefix):]
        links = load()
        remaining = [l for l in links if l["code"] != code]
        if len(remaining) == len(links):
            return self.send_json(404, {"error": "link not found"})
        save(remaining)
        return self.send_json(200, {"ok": True})


